static int compareAisle(const void *left, const void *right) {
  long long a = *(const long long *)left;
  long long b = *(const long long *)right;
  return (a > b) - (a < b);
}

long long solve(const long long *values, int n) {
  if (n <= 0) return 0;
  long long *a = (long long *)malloc(sizeof(long long) * (size_t)n);
  memcpy(a, values, sizeof(long long) * (size_t)n);
  qsort(a, (size_t)n, sizeof(long long), compareAisle);
  long long best = 1, run = 1;
  for (int i = 1; i < n; i++) {
    if (a[i] == a[i - 1]) continue;
    if (a[i] == a[i - 1] + 1) run++;
    else run = 1;
    if (run > best) best = run;
  }
  free(a);
  return best;
}

