long long solve(const long long *values, int n) {
  if (n < 2) return 0;
  long long w = values[0];
  int m = n - 1;
  const long long *a = values + 1;
  int *maxq = (int *)malloc(sizeof(int) * (size_t)m);
  int *minq = (int *)malloc(sizeof(int) * (size_t)m);
  int maxHead = 0, maxTail = 0, minHead = 0, minTail = 0;
  long long best = 0;
  int seen = 0;
  for (int i = 0; i < m; i++) {
    while (maxTail > maxHead && a[maxq[maxTail - 1]] <= a[i]) maxTail--;
    maxq[maxTail++] = i;
    while (minTail > minHead && a[minq[minTail - 1]] >= a[i]) minTail--;
    minq[minTail++] = i;
    if ((long long)maxq[maxHead] <= (long long)i - w) maxHead++;
    if ((long long)minq[minHead] <= (long long)i - w) minHead++;
    if ((long long)i >= w - 1) {
      long long spread = a[maxq[maxHead]] - a[minq[minHead]];
      if (!seen || spread < best) { best = spread; seen = 1; }
    }
  }
  free(maxq);
  free(minq);
  return best;
}

