def solve(values: list[int]) -> int:
    from collections import deque

    if len(values) < 2:
        return 0
    w = values[0]
    a = values[1:]
    m = len(a)
    maxq: deque[int] = deque()
    minq: deque[int] = deque()
    best = None
    for i in range(m):
        v = a[i]
        while maxq and a[maxq[-1]] <= v:
            maxq.pop()
        maxq.append(i)
        while minq and a[minq[-1]] >= v:
            minq.pop()
        minq.append(i)
        if maxq[0] <= i - w:
            maxq.popleft()
        if minq[0] <= i - w:
            minq.popleft()
        if i >= w - 1:
            spread = a[maxq[0]] - a[minq[0]]
            if best is None or spread < best:
                best = spread
    return 0 if best is None else best

